"""
Solve the closed-shell direct RPA response problem in

the spin-orbital basis, with the Hartree kernel only. Include every

same-spin occupied-to-virtual excitation. Return the excitation

energies together with their forward (X) and backward (Y) amplitudes.

The random-phase approximation used to screen

the Coulomb interaction in GW-based theories is the direct RPA. Only

the bare (Hartree-type) part of the electron-electron interaction

enters, never the exchange part. For a closed-shell reference in

spin-orbitals, an excitation pairs one occupied spin-orbital with one

virtual spin-orbital of the same spin. The eigenvalue problem is

non-Hermitian in its natural (A, B) form. It can be solved through the

Hermitian matrix (A-B)^(1/2) (A+B) (A-B)^(1/2), whose eigenvalues are the

squared excitation energies.

Returns
-------
a  tuple (omega, X, Y). omega is a list of the     excitation energies, one per occupied-virtual pair, in ascending     order. X is a list of the same length. X[nu] is a list over the     occupied-virtual pairs, in the order defined above, that gives the     forward amplitude of excitation nu on each pair. Y is the     corresponding list of backward amplitudes.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def direct_rpa(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
) -> tuple[list[float], list[list[float]], list[list[float]]]:
    """
    Solve the direct RPA problem for a set of active spin-orbitals.

    Args:
        eps: orbital energy of each active spin-orbital, indexed 0..n-1.
            Spin-orbital 2*p is the alpha member of spatial orbital p,
            and spin-orbital 2*p+1 is the beta member. Both have the
            same energy.
        chem_spatial: two-electron Coulomb integrals over the active
            spatial orbitals, in chemist notation (pq|rs), keyed by the
            4-tuple (p, q, r, s) of spatial-orbital indices. A key that
            is absent has value 0.0. The corresponding spin-orbital
            integral (p', q', r', s') is chem_spatial[(p'//2, q'//2,
            r'//2, s'//2)] if p', q' have the same spin and r', s' have
            the same spin. In all other cases it is 0.0.
        occ: the occupied active spin-orbital indices.
        vir: the virtual active spin-orbital indices.

    Conventions:
        - The occupied-virtual pair list pairs every occupied
          spin-orbital with every virtual spin-orbital of the same spin
          (the same spin-orbital index parity). The order is occ[0]
          with every same-spin member of vir, then occ[1] with every
          same-spin member of vir, and so on. The order of occ and vir
          is preserved as given.
        - Excitation energies are returned sorted in ascending order,
          together with their amplitudes in the same order.
        - Each amplitude pair (X, Y) for a given excitation is
          normalized so that sum(X[k]**2) - sum(Y[k]**2) == 1. The
          overall sign is fixed by the eigenvector sign convention of
          the symmetric eigensystem step. That convention is applied to
          the Hermitian matrix (A-B)^(1/2) (A+B) (A-B)^(1/2), whose
          eigenvalues are the squared excitation energies. It is not
          applied to (A-B) itself, whose own eigenvectors do not
          determine this sign.

    """
    return ([], [], [])

# =============================================================================
# GOLD SOLUTION
# =============================================================================

def _oracle_direct_rpa(
    eps: list[float],
    chem_spatial: dict[tuple[int, int, int, int], float],
    occ: list[int],
    vir: list[int],
) -> tuple[list[float], list[list[float]], list[list[float]]]:
    ov = [(i, a) for i in occ for a in vir if i % 2 == a % 2]
    npairs = len(ov)

    def _phys(p, q, r, s):
        if p % 2 != r % 2 or q % 2 != s % 2:
            return 0.0
        return chem_spatial.get((p//2, r//2, q//2, s//2), 0.0)

    A = [[0.0]*npairs for _ in range(npairs)]
    B = [[0.0]*npairs for _ in range(npairs)]
    for I, (i, a) in enumerate(ov):
        for J, (j, b) in enumerate(ov):
            A[I][J] = (eps[a]-eps[i])*(1.0 if (i == j and a == b) else 0.0) + _phys(a, j, i, b)
            B[I][J] = _phys(a, b, i, j)
    AmB = [[A[p][q]-B[p][q] for q in range(npairs)] for p in range(npairs)]
    ApB = [[A[p][q]+B[p][q] for q in range(npairs)] for p in range(npairs)]

    wA, vA = _oracle_symmetric_eigensystem(AmB)
    # vA[k] is the k-th eigenvector (a list over components); vA[k][p] is its p-th component.
    sqrtwA = [max(w, 1e-300)**0.5 for w in wA]
    s_mat = [[sum(vA[k][p]*sqrtwA[k]*vA[k][q] for k in range(npairs)) for q in range(npairs)] for p in range(npairs)]
    sinv_mat = [[sum(vA[k][p]*(1.0/sqrtwA[k])*vA[k][q] for k in range(npairs)) for q in range(npairs)] for p in range(npairs)]

    prod = [[sum(s_mat[p][k]*ApB[k][q] for k in range(npairs)) for q in range(npairs)] for p in range(npairs)]
    Mmid = [[sum(prod[p][k]*s_mat[k][q] for k in range(npairs)) for q in range(npairs)] for p in range(npairs)]
    Mmid = [[0.5*(Mmid[p][q]+Mmid[q][p]) for q in range(npairs)] for p in range(npairs)]

    o2, T = _oracle_symmetric_eigensystem(Mmid)
    omega = [max(v, 0.0)**0.5 for v in o2]

    X = [[0.0]*npairs for _ in range(npairs)]
    Y = [[0.0]*npairs for _ in range(npairs)]
    for nu in range(npairs):
        om = max(omega[nu], 1e-300)
        xpy = [sum(s_mat[p][k]*T[nu][k] for k in range(npairs))/(om**0.5) for p in range(npairs)]
        xmy = [sum(sinv_mat[p][k]*T[nu][k] for k in range(npairs))*(om**0.5) for p in range(npairs)]
        for p in range(npairs):
            X[p][nu] = 0.5*(xpy[p]+xmy[p])
            Y[p][nu] = 0.5*(xpy[p]-xmy[p])

    order = sorted(range(npairs), key=lambda nu: omega[nu])
    omega_sorted = [omega[nu] for nu in order]
    X_sorted = [[X[p][nu] for p in range(npairs)] for nu in order]
    Y_sorted = [[Y[p][nu] for p in range(npairs)] for nu in order]
    return (omega_sorted, X_sorted, Y_sorted)

